//! Rust translation of `trace/events/power_cpu_migrate.h`.
//!
//! The C source uses the Linux tracepoint-definition framework.  The
//! framework-provided declaration and event-generation machinery is external
//! to this file; the entry layout, event names, and local constant are kept
//! here.

#[repr(C)]
#[derive(Copy, Clone)]
pub struct CpuMigrateEntry {
    pub timestamp: u64,
    pub cpu_hwid: u32,
}

/// The tracepoint event names generated by `DEFINE_EVENT`.
#[repr(u8)]
#[derive(Copy, Clone, Eq, PartialEq)]
pub enum CpuMigrateEvent {
    Begin = 0,
    Finish = 1,
    Current = 2,
}

/// Equivalent of the C `CPU_MIGRATE_ALL_CPUS` macro.
pub const CPU_MIGRATE_ALL_CPUS: u32 = 0x8000_0000u32;

/*
 * C tracepoint declarations represented above:
 *
 *   DECLARE_EVENT_CLASS(cpu_migrate, ...)
 *   DEFINE_EVENT(cpu_migrate, cpu_migrate_begin, ...)
 *   DEFINE_EVENT(cpu_migrate, cpu_migrate_finish, ...)
 *   DEFINE_EVENT(cpu_migrate, cpu_migrate_current, ...)
 *
 * The C `TP_fast_assign` operation is the direct field assignment performed
 * when an event entry is populated:
 *
 *   entry.timestamp = timestamp;
 *   entry.cpu_hwid = cpu_hwid;
 *
 * The C `TP_printk` format is:
 *   "timestamp=%llu cpu_hwid=0x%08lX"
 */


